def is_perfect_cube(n):
    if n < 0:
        return False
    # Handle 0 separately, though q^2 - q + 1 is always positive for q >= 1
    if n == 0:
        return True, 0

    # Calculate the integer cube root
    k = round(n**(1/3))

    # Check if k^3 actually equals n
    if k * k * k == n:
        return True, k
    return False, None

