def check_solution(q):
    """Checks if q is prime, calculates q^2 - q + 1, checks if it's a perfect cube p^3,
    and if p is prime and p != q."""

    # We assume q is passed in as prime based on problem constraints.
    value = q**2 - q + 1

    # Find the cube root
    p_float = value**(1/3)
    p_int = round(p_float)

    # Check if it is a perfect cube
    if p_int**3 == value:
        p = p_int

        # Primality check for p
        def is_prime(n):
            if n < 2:
                return False
            for i in range(2, int(n**0.5) + 1):
                if n % i == 0:
                    return False
            return True

        if is_prime(p):
            if p != q:
                print(f"Found solution: q={q}, p={p}")
                return True
            else:
                print(f"Condition p != q failed for q={q}")
                return False
        else:
            print(f"p={p} is not prime for q={q}")
            return False
    else:
        print(f"Value {value} for q={q} is not a perfect cube.")
        return False

