def check_solution(k):
    if not is_prime(k):
        return None

    # Solve m^2 = 4k^3 - 3
    m_squared = 4 * (k**3) - 3
    if m_squared < 0:
        return None

    m = int(math.sqrt(m_squared))
    if m*m == m_squared:
        # We found an integer m. Calculate q.
        # q = (1 + m) / 2
        if (1 + m) % 2 == 0:
            q = (1 + m) // 2
            if is_prime(q) and k != q:
                return q
    return None

